INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Schutzplan für IT-Systeme immer nur technische Maßnahmen umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Maßnahmen nötig"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist zentral für einen IT-Schutzplan?', 3, '[{"text": "Risikobewertung", "correct": true, "because": "Identifiziert Bedrohungen"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem Schutzplan?', 5, '[{"text": "Firewall", "correct": true, "because": "Schützt Netzwerk"}, {"text": "Schulungen", "correct": true, "because": "Erhöhen Awareness"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzen Zugriff"}, {"text": "Dekoratives Design", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Schutzplan berücksichtigt Risiken. b) Er wird einmal erstellt und nie angepasst.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, regelmäßige Anpassung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines Schutzplans?', 4, '[{"text": "Bedrohungsszenarien", "correct": false, "because": "Bestimmen Maßnahmen"}, {"text": "Schutzziele", "correct": false, "because": "Definieren Anforderungen"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Schutzplan nur für Datenbanken gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst Netzwerke, Clients, Prozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört zu einem Schutzplan?', 4, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Datenintegrität"}, {"text": "Schnelle Installation", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Schutzplan immer teuer ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kosteneffizient durch Priorisierung"}, {"text": "Ja", "correct": false, "because": "Kosten abhängig von Umfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Umfasst ein Schutzplan nur technische Lösungen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Maßnahmen"}, {"text": "Ja", "correct": false, "because": "Ganzheitlicher Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzziele verfolgt ein Schutzplan?', 5, '[{"text": "Vertraulichkeit", "correct": true, "because": "Schützt Daten"}, {"text": "Integrität", "correct": true, "because": "Verhindert Manipulation"}, {"text": "Verfügbarkeit", "correct": true, "because": "Sichert Zugriff"}, {"text": "Schnelligkeit", "correct": false, "because": "Kein Sicherheitsziel"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Schutzplan?', 4, '[{"text": "Risikominimierung", "correct": true, "because": "Schützt kritische Assets"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Präsentationsstil", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Schutzplan schützt vor Bedrohungen. b) Er verhindert alle Angriffe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, minimiert nur Risiken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Schutzplan?', 3, '[{"text": "Risikoanalyse", "correct": false, "because": "Bestimmt Bedrohungen"}, {"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Schützen Systeme"}, {"text": "Dekorative Diagramme", "correct": true, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich einen Schutzplan entwickle?', 4, '[{"text": "Risiken analysieren, Maßnahmen definieren", "correct": true, "because": "Strukturierter Ansatz"}, {"text": "Nur Firewall installieren", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Plan starten", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Schutzplan nur für große Firmen relevant ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch KMUs brauchen Schutz"}, {"text": "Ja", "correct": "false", "because": "Universelle Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, einen Schutzplan effektiv zu gestalten?', 4, '[{"text": "Schichtensicherheit", "correct": true, "because": "Mehrstufiger Schutz"}, {"text": "Einzelmaßnahmen", "correct": false, "because": "Zu begrenzt"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Schutzplan regelmäßig überprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Bedrohungen erfordern Anpassung"}, {"text": "Nein", "correct": false, "because": "Überprüfung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gut durchdachter Schutzplan?', 5, '[{"text": "Risikoreduktion", "correct": true, "because": "Minimiert Bedrohungen"}, {"text": "Vertrauensschutz", "correct": true, "because": "Schützt Reputation"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Visuals", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Schutzplan unwichtig?', 3, '[{"text": "Bedrohungsszenarien", "correct": false, "because": "Bestimmen Maßnahmen"}, {"text": "Zugriffskontrollen", "correct": false, "because": "Schützen Daten"}, {"text": "Bürofarben", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Netzwerk sichern will?', 4, '[{"text": "Risiken bewerten, Firewall und Schulungen einrichten", "correct": true, "because": "Ganzheitlicher Schutz"}, {"text": "Nur Antivirenprogramm nutzen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Maßnahmen starten", "correct": false, "because": "Unsicher"}]');
